// --- PASSO B: PROCESSAR QUANTIDADE E ATUALIZAR COMBO ---

const estadoAtual = $items("Start")[0].json;

const mensagemRaw = $json.mensagem_cliente
  ? $json.mensagem_cliente.toString().trim()
  : "";

const quantidadeDigitada = parseInt(mensagemRaw, 10);
const jid = estadoAtual.Jid;

// --- PARSE SEGURO ---
let combo = {};
let itemPendente = {};
let carrinho = [];

try {
  combo = typeof estadoAtual.combo_em_montagem === "string"
    ? JSON.parse(estadoAtual.combo_em_montagem)
    : estadoAtual.combo_em_montagem || {};

  itemPendente = typeof estadoAtual.item_pendente_combo === "string"
    ? JSON.parse(estadoAtual.item_pendente_combo)
    : estadoAtual.item_pendente_combo || {};

  carrinho = typeof estadoAtual.carrinho_json === "string"
    ? JSON.parse(estadoAtual.carrinho_json)
    : estadoAtual.carrinho_json || [];

} catch {
  return [{
    json:{
      erro:true,
      mensagemResposta:"Erro técnico. Reiniciando...",
      sql:`UPDATE conversas_bot
           SET estado_conversa='menu_inicio',
               combo_em_montagem=NULL,
               item_pendente_combo=NULL
           WHERE jid='${jid}'`
    }
  }];
}

// --- VALIDA QUANTIDADE ---
if (isNaN(quantidadeDigitada) || quantidadeDigitada <= 0) {
  return [{
    json:{
      erro:true,
      mensagemResposta:"Digite um número válido."
    }
  }];
}

const etapa = combo.etapas?.[combo.etapaAtual];
if (!etapa) {
  return [{
    json:{
      erro:true,
      mensagemResposta:"Erro no fluxo do combo."
    }
  }];
}

if (!Array.isArray(etapa.escolhidos)) etapa.escolhidos = [];

// =====================================================
// 🔥 REGRA POR SABOR
// =====================================================

let limiteSabor = Infinity;

if (etapa.regra?.includes("_por_sabor")) {
  limiteSabor = parseInt(etapa.regra.split("_")[0], 10);
}

const jaTemMesmoSabor =
  etapa.escolhidos.filter(i => i.id === itemPendente.id).length;

const restanteSabor = limiteSabor - jaTemMesmoSabor;

if (jaTemMesmoSabor + quantidadeDigitada > limiteSabor) {
  return [{
    json:{
      erro:true,
      mensagemResposta:
`Você pode adicionar no máximo ${restanteSabor} unidade(s) desse item.
(${itemPendente.nome}

Envie novamente a quantidade.`
    }
  }];
}

// =====================================================
// 🔥 LIMITE TOTAL DO COMBO
// =====================================================

const totalAtualCombo = combo.etapas
  .flatMap(e => e.escolhidos || [])
  .length;

const qtdNecessaria = parseInt(combo.qtd_necessaria || 0, 10);

const restanteCombo = qtdNecessaria - totalAtualCombo;

if (totalAtualCombo + quantidadeDigitada > qtdNecessaria) {
  return [{
    json:{
      erro:true,
      mensagemResposta:
`Você pode adicionar no máximo ${restanteCombo} unidade(s) desse item.
(${itemPendente.nome}

Envie novamente a quantidade.`
    }
  }];
}

// --- ADICIONA ITEM ---
for (let i = 0; i < quantidadeDigitada; i++) {
  etapa.escolhidos.push({
    id: itemPendente.id,
    nome: itemPendente.nome,
    preco_original: itemPendente.preco
  });
}

// =====================================================
// 🔥 TOTAL GERAL DO COMBO
// =====================================================

const totalEscolhidos = combo.etapas
  .flatMap(e => e.escolhidos || [])
  .length;

// --- FINALIZA COMBO ---
if (totalEscolhidos >= qtdNecessaria) {

  const agrupados = {};

  combo.etapas.forEach(etapa => {
    (etapa.escolhidos || []).forEach(item => {
      if (!agrupados[item.nome]) {
        agrupados[item.nome] = 0;
      }
      agrupados[item.nome]++;
    });
  });

  const descricaoItens = Object.entries(agrupados)
    .map(([nome, qtd]) => `${qtd}x ${nome}`)
    .join("\n");

// agrupa itens internos do combo
const agrupadosInternos = {};

combo.etapas.forEach(etapa => {
  (etapa.escolhidos || []).forEach(item => {
    if (!agrupadosInternos[item.id]) {
      agrupadosInternos[item.id] = {
        id: item.id,
        nome: item.nome,
        qtd: 0
      };
    }
    agrupadosInternos[item.id].qtd++;
  });
});

const itensInternos = Object.values(agrupadosInternos);

// adiciona combo no carrinho COM itens internos
carrinho.push({
  id: combo.id_combo,
  indice: combo.indice,
  qtd: 1,
  nome: combo.nome,
  precoUnitario: parseFloat(combo.preco),
  itens_internos: itensInternos
});


  return [{
    json:{
      finalizado:true,
      mensagemResposta:`Combo montado! 🎉\n\n*${combo.nome}:*\n\n${descricaoItens}\n`,
      sql:`UPDATE conversas_bot
           SET carrinho_json='${JSON.stringify(carrinho)}'::jsonb,
               combo_em_montagem=NULL,
               item_pendente_combo=NULL,
               estado_conversa='visualizando_carrinho',
               ultima_interacao=NOW()
           WHERE jid='${jid}'`
    }
  }];
}

// =====================================================
// 🔥 TROCA CATEGORIA SE LIMITE SABOR ATINGIDO
// =====================================================

let limiteSaborAtingido = false;

if (limiteSabor !== Infinity) {
  const totalMesmoItem =
    etapa.escolhidos.filter(i => i.id === itemPendente.id).length;

  limiteSaborAtingido = totalMesmoItem >= limiteSabor;
}

if (limiteSaborAtingido && combo.etapas.length > 1) {
  combo.etapaAtual++;
  if (combo.etapaAtual >= combo.etapas.length)
    combo.etapaAtual = combo.etapas.length - 1;
}

const categoriaAtual = combo.etapas[combo.etapaAtual].categoria;

// --- RESPOSTA NORMAL ---
return [{
  json:{
    buscar_novo_menu:true,
    proxima_categoria: categoriaAtual,
    limite_sabor: limiteSaborAtingido,
    mensagemResposta:`Adicionado!\nFaltam ${qtdNecessaria - totalEscolhidos} item(ns).`,
    sql:`UPDATE conversas_bot
         SET combo_em_montagem='${JSON.stringify(combo)}'::jsonb,
             item_pendente_combo=NULL,
             estado_conversa='montando_combo',
             ultima_interacao=NOW()
         WHERE jid='${jid}'`
  }
}];

// --- CÓDIGO SIMPLIFICADO PARA EXTRAIR ID E QUANTIDADE ---

// 1. Pega os dados de entrada
const estadoAtual = $items("Start")[0].json;
const quantidade = parseInt(estadoAtual.mensagem_cliente, 10);

// 2. Validação da quantidade
if (isNaN(quantidade) || quantidade < 0) { // Permite 0 para remoção
// Retorna um objeto de erro se a quantidade for inválida
return [{
json: {
error: "Quantidade inválida",
mensagemResposta: "Por favor, digite uma quantidade válida.😕"
}
}];
}

// 3. Processa os dados do estado para encontrar o item
const mapaId = (typeof estadoAtual.item_pendente_combo === 'string') ? JSON.parse(estadoAtual.item_pendente_combo) : (estadoAtual.item_pendente_combo || {});

// 5. Retorna apenas o ID real e a quantidade
return [{
json: {
realId: mapaId.id,
quantidade: quantidade,
preco: mapaId.preco.toFixed(2),
nome: mapaId.nome
}
}];

// --- EXTRAI IDS DE ITENS QUE ATINGIRAM LIMITE POR SABOR ---

const input = $items("Code in JavaScript")[0].json;

// 1. Extrai JSON do combo dentro do SQL
let combo = {};

try {
  const match = input.sql.match(/combo_em_montagem='(.+?)'::jsonb/);
  if (!match) throw "Combo não encontrado";

  combo = JSON.parse(match[1]);

} catch (e) {
  return [{
    json:{
      erro:true,
      mensagem:"Erro ao extrair combo_em_montagem"
    }
  }];
}

// 2. Percorre etapas e verifica limites
const idsLimiteAtingido = [];

(combo.etapas || []).forEach(etapa => {

  if (!etapa.regra || !etapa.regra.includes("_por_sabor")) return;

  const limite = parseInt(etapa.regra.split("_")[0], 10);
  if (!limite) return;

  const contagem = {};

  (etapa.escolhidos || []).forEach(item => {
    contagem[item.id] = (contagem[item.id] || 0) + 1;
  });

  Object.entries(contagem).forEach(([id,qtd])=>{
    if (qtd >= limite) idsLimiteAtingido.push(id);
  });

});

// remove duplicados
const idsUnicos = [...new Set(idsLimiteAtingido)];

return [{
  json:{
    ids_limite_atingido: idsUnicos
  }
}];

// --- FORMATA CARDÁPIO EXCLUINDO ITENS QUE ATINGIRAM LIMITE + MAPA_ID_JSON ---

// itens do cardápio vêm do node anterior (Notion / Buscar Cardápio)
const itensCardapio = $input.all().map(i => i.json);

// dados do node "trata dados"
const dadosExtras = $items("trata dados")?.[0]?.json || {};

// ids a excluir
let itensExcluidos = dadosExtras.itens_excluidos || [];

if (typeof itensExcluidos === "string") {
  try {
    itensExcluidos = JSON.parse(itensExcluidos);
  } catch {
    itensExcluidos = [];
  }
}

// filtra estoque + remove itens que atingiram limite
const itensFiltrados = itensCardapio.filter(item =>
  parseInt(item.property_estoque, 10) > 0 &&
  !itensExcluidos.includes(item.property_id)
);

// --- FORMATA TEXTO + CRIA MAPA ---
let menuTexto = "";
let mapaId = {};

for (const item of itensFiltrados) {

  const indice = item.property_ndice;
  if (!indice) continue;

  let linha = `*${indice})*\u200B`;

  if (item.property_em_promo) {
    linha += ` 🎁`;
  } else {
    linha += ` 🍫`;
  }

  linha += ` ${item.property_nome}`;

  if (item.property_medida) {
    linha += ` (${item.property_medida})`;
  }

  if (item.property_descri_o?.trim()) {
    linha += `\n\n_*Descrição:*_\n${item.property_descri_o.trim()}`;
  }

  menuTexto += linha + `\n\n`;

  // --- CRIA MAPA_ID_JSON ---
  const precoFinal =
    parseFloat(item.property_pre_o_promo) > 0
      ? parseFloat(item.property_pre_o_promo)
      : parseFloat(item.property_pre_o);

  mapaId[indice] = {
    id: item.property_id,
    nome: item.property_nome,
    preco: precoFinal,
    estq: item.property_estoque
  };
}

// fallback
if (!menuTexto) {
  menuTexto =
    "🚫 Desculpe, não temos itens disponíveis no momento.";
}

menuTexto += "ㅤ";

// retorno final
return [{
  json: {
    menu_formatado: menuTexto,
    mapa_id_json: JSON.stringify(mapaId)
  }
}];

// --- FORMATA CARDÁPIO + CRIA MAPA_ID_JSON ---

// itens vêm do node anterior (Notion / Buscar Cardápio)
const itensCardapio = $input.all().map(i => i.json);

// filtra apenas estoque disponível
const itensFiltrados = itensCardapio.filter(item =>
  parseInt(item.property_estoque, 10) > 0
);

// --- FORMATA TEXTO E CRIA MAPA ---
let menuTexto = "";
let mapaId = {};

for (const item of itensFiltrados) {

  const indice = item.property_ndice;
  if (!indice) continue;

  let linha = `*${indice})*\u200B`;

  if (item.property_em_promo) {
    linha += ` 🎁`;
  } else {
    linha += ` 🍫`;
  }

  linha += ` ${item.property_nome}`;

  if (item.property_medida) {
    linha += ` (${item.property_medida})`;
  }

  if (item.property_descri_o?.trim()) {
    linha += `\n\n_*Descrição:*_\n${item.property_descri_o.trim()}`;
  }

  menuTexto += linha + `\n\n`;

  // --- CRIA MAPA_ID_JSON ---
  const precoFinal =
    parseFloat(item.property_pre_o_promo) > 0
      ? parseFloat(item.property_pre_o_promo)
      : parseFloat(item.property_pre_o);

  mapaId[indice] = {
    id: item.property_id,
    nome: item.property_nome,
    preco: precoFinal,
    estq: item.property_estoque
  };
}

// fallback caso vazio
if (!menuTexto) {
  menuTexto = "🚫 Nenhum item disponível no momento.";
}

menuTexto += "ㅤ";

// retorno final
return [{
  json: {
    menu_formatado: menuTexto,
    mapa_id_json: JSON.stringify(mapaId)
  }
}];

